const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle,
  LevelFormat, TableOfContents, PageBreak, PageNumber, Footer, Header
} = require("docx");

// ---------- helpers ----------
const FONT = "Calibri";
const BODY = 22; // 11 pt
const H = (t, lvl) => new Paragraph({ heading: lvl, children: [new TextRun({ text: t })] });
// Rich text: *italic* toggles (when stars is true), _{sub} and ^{sup}; bare tokens such as N_d, r_e, S_LWP
// are typeset with a true subscript.
const SUBRE = /(?:(?<![A-Za-z0-9_])(ACI|SO|[A-Za-z])|([τασκβρξχωλ]))_([A-Za-z0-9∗]{1,4})(?![A-Za-z0-9_{])/g;
const rich = (t, o = {}) => {
  const size = o.size || BODY, stars = o.stars !== false;
  t = t.replace(SUBRE, (mm, a, b, c) => (a || b) + "_{" + c + "}");
  const out = []; let it = false, buf = "";
  const mk = (text, extra = {}) => new TextRun({ text, italics: it || !!o.italics, bold: !!o.bold, font: FONT, size, ...extra });
  const flush = () => { if (buf) { out.push(mk(buf)); buf = ""; } };
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (stars && c === "*") { flush(); it = !it; continue; }
    if ((c === "_" || c === "^") && t[i + 1] === "{") {
      const j = t.indexOf("}", i + 2);
      if (j > 0) { flush(); out.push(mk(t.slice(i + 2, j), c === "_" ? { subScript: true } : { superScript: true })); i = j; continue; }
    }
    buf += c;
  }
  flush();
  return out.length ? out : [mk("")];
};
const P = (t, opts = {}) => new Paragraph({ children: rich(t), spacing: { after: 160, line: 276 }, alignment: AlignmentType.JUSTIFIED, ...opts });
const Bullet = (t) => new Paragraph({ numbering: { reference: "bullets", level: 0 }, children: rich(t, { stars: false }), spacing: { after: 80, line: 276 } });
const PB = (lead, t) => new Paragraph({ children: rich(lead, { bold: true, stars: false }).concat(rich(t)), spacing: { after: 160, line: 276 }, alignment: AlignmentType.JUSTIFIED });
const Num = (t, ref = "nums") => new Paragraph({ numbering: { reference: ref, level: 0 }, children: rich(t, { stars: false }), spacing: { after: 80, line: 276 } });
const Ref = (t) => new Paragraph({ children: [new TextRun({ text: t, font: FONT, size: 20 })], spacing: { after: 100, line: 260 }, indent: { left: 720, hanging: 720 } });
const Note = (t) => new Paragraph({ children: [new TextRun({ text: t, font: FONT, size: 20, italics: true })], spacing: { after: 160, line: 260 }, indent: { left: 360, right: 360 } });

const cell = (t, w, bold = false, shade = null) => new TableCell({
  width: { size: w, type: WidthType.DXA },
  shading: shade ? { type: ShadingType.CLEAR, fill: shade, color: "auto" } : undefined,
  margins: { top: 60, bottom: 60, left: 100, right: 100 },
  children: [new Paragraph({ children: rich(t, { bold, size: 20, stars: false }), spacing: { after: 0, line: 260 } })]
});

// ---------- content ----------
const children = [];

// Title block
children.push(new Paragraph({ children: [new TextRun({ text: "Aerosol–Cloud Interactions and Their Radiative Impacts", bold: true, font: FONT, size: 40 })], alignment: AlignmentType.CENTER, spacing: { after: 120 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "A Chronological Literature Review, from Twomey to the Present", font: FONT, size: 28 })], alignment: AlignmentType.CENTER, spacing: { after: 120 } }));
children.push(new Paragraph({ children: [new TextRun({ text: "Prepared for Andrew Buggee, Scripps Institution of Oceanography — 10 November 2026 (revision 4: adds Section 7 on the physics behind the results, with equations and figures, and renumbers the later sections; revision 3 added the section on questions addressable within the EPCAPE turbulence–brightness project, now Section 12; revision 2 added the Hobbs, 1993, audit)", font: FONT, size: 22, italics: true })], alignment: AlignmentType.CENTER, spacing: { after: 400 } }));

children.push(H("Abstract", HeadingLevel.HEADING_1));
children.push(P("This review traces the development of research on how aerosol particles alter the radiative properties of warm (liquid) clouds, from Sean Twomey's activation theory and albedo hypothesis through the present-day effort to bound the effective radiative forcing of aerosol–cloud interactions (ERFaci). It is organized chronologically in five eras: (1) the foundational theory of the 1950s–1970s; (2) the first observational and modeling tests of the 1980s–1990s, including ship tracks, the Albrecht precipitation-suppression hypothesis, and the albedo-susceptibility framework; (3) the satellite and ground-based remote-sensing era of the 2000s, in which the first indirect effect was measured statistically and the entrainment–sedimentation feedback was discovered; (4) the 2010s, in which liquid-water-path (LWP) adjustments, natural experiments, retrieval uncertainty and the scale problem reframed the question; and (5) the current decade, in which machine-learning ship-track detection, the IMO 2020 fuel regulation, morphology-conditioned susceptibilities, and new ground-based campaigns such as EPCAPE are being used to close the remaining gaps. A physics section then steps through the mechanisms behind these results (activation, condensational growth, coalescence, extinction, multiple scattering, absorption and entrainment) with equations, worked numbers and figures, drawing on two textbooks and three sets of course and reference material. A further section singles out the surface-radiation perspective, which is comparatively under-exploited and is the natural entry point for a radiation scientist working with ARM data. The review closes with a table of what is settled versus contested, a list of open questions, and a suggested reading order. This revision adds an audit of the outstanding problems stated in the 1993 volume *Aerosol–Cloud–Climate Interactions* (Hobbs, 1993) against the 2026 literature, identifying which of those problems have been resolved and which remain open. A final section maps the open questions onto the DOE ASR project that funds this work, *Connecting Aerosol-Related Cloud Brightness to Turbulence using EPCAPE Measurements* (Miller et al., 2024), and identifies those that fall within its radiation and retrieval tasks without overlapping the turbulence work assigned to its principal investigator."));

// TOC
children.push(H("Contents", HeadingLevel.HEADING_1));
children.push(new TableOfContents("Contents", { hyperlink: true, headingStyleRange: "1-2" }));
children.push(new Paragraph({ children: [new PageBreak()] }));

// 1. Introduction
children.push(H("1. Introduction", HeadingLevel.HEADING_1));
children.push(H("1.1 Scope and purpose", HeadingLevel.HEADING_2));
children.push(P("The subject of this review is the radiative consequence of aerosol particles acting as cloud condensation nuclei (CCN) in warm, liquid-phase boundary-layer clouds: how added particles change droplet number (N_d), droplet effective radius (r_e), liquid water path (LWP), cloud fraction, and ultimately the shortwave radiation reflected to space and transmitted to the surface. Ice and mixed-phase clouds, aerosol–radiation interactions (the 'direct' effect), and the semi-direct effect of absorbing aerosol are mentioned only where they bear on the warm-cloud story. The geographic emphasis is on marine stratocumulus, because that regime dominates the global ERFaci and is the regime sampled by EPCAPE."));
children.push(P("The review is intended as a road map for a reader with a strong background in radiative transfer and cloud microphysics who is new to the aerosol–cloud–radiation literature specifically. It therefore spends more time on the physical arguments and the methodological turning points than on tabulating every result, and it flags where the field's consensus has shifted and why."));

children.push(H("1.2 How sources were selected", HeadingLevel.HEADING_2));
children.push(P("Sources were assembled in two passes. The first pass identified the papers that the major review articles and assessment reports consistently credit as turning points (Lohmann and Feichter, 2005; Stevens and Feingold, 2009; Mülmenstädt and Feingold, 2018; Grosvenor et al., 2018; Bellouin et al., 2020; Quaas et al., 2020; Christensen et al., 2022). The second pass followed the citation trails from those reviews forward to the most recent work (2020–2026), with particular attention to studies that use Atmospheric Radiation Measurement (ARM) ground-based data and to the three EPCAPE papers published or in review as of this writing. Every paper cited here was located and its bibliographic details verified against the publisher record, a repository copy, or the paper itself. Where only an abstract was available, the claim attributed to the paper is restricted to what the abstract states. The reference list gives a DOI for every entry for which one was confirmed."));
children.push(P("A third source is the edited volume *Aerosol–Cloud–Climate Interactions* (Hobbs, 1993), whose chapters close with explicit statements of the outstanding problems as their authors saw them in 1992–1993. Those statements are used in Sections 3.5 and 10.2 as a benchmark: each problem is restated in the chapter author's own terms, then assessed against the later literature, with the status judgment and the sources it rests on given explicitly so that the reader can check or dispute it. Problems in that volume concerning ice and cirrus microphysics, stratospheric aerosol, cloud parameterization in general, and cloud feedbacks on climate sensitivity lie outside the scope of this review and are noted only where they touch warm-cloud aerosol–cloud interactions."));

children.push(P("A fourth group of sources supports the physics section (Section 7): the textbooks of Rogers and Yau (1989) and Bohren and Clothiaux (2006), two lecture decks from an MIT course (Ardon-Dryer and Garimella, 2014a, 2014b), the encyclopedia article of Li et al. (2017), and Robert Wood's notes on seminal papers from his University of Washington course on aerosol–cloud–climate interactions (Wood, 2015). These were supplied by the reader and are treated as authoritative for the physics. Figures redrawn from them were recomputed from the source equations and checked against the values tabulated in the originals. Wood's notes are informal course material and are cited as such; where they summarize a paper, the paper itself is the primary source."));
children.push(H("1.3 Organization and key terms", HeadingLevel.HEADING_2));
children.push(P("Sections 2–6 proceed chronologically. Section 7 steps through the physics and chemistry behind the results of those sections, with equations and figures, and can be read before them or alongside them. Section 8 steps outside the chronology to treat surface radiation as a theme, because it cuts across all eras and because it is the perspective most relevant to EPCAPE. Section 9 synthesizes, Section 10 lists open questions (Section 10.1 from the recent literature, Section 10.2 from the 1993 audit), Section 11 gives a reading order, and Section 12 identifies which of the open questions can be addressed within the EPCAPE turbulence–brightness project."));
children.push(P("A few terms recur. The *Twomey effect* (also 'first indirect effect', 'cloud albedo effect', or in modern assessment language the instantaneous radiative forcing from aerosol–cloud interactions, RFaci) is the increase in cloud albedo caused by more numerous, smaller droplets at fixed liquid water. *Adjustments* (historically 'second indirect effects', including the 'Albrecht' or 'lifetime' effect) are the subsequent changes in LWP, cloud fraction, and cloud lifetime that follow from the microphysical change. The sum of the Twomey effect and the adjustments is the *effective radiative forcing*, ERFaci. *Albedo susceptibility* is the derivative of cloud albedo with respect to droplet number, and *ACI metrics* are the various logarithmic sensitivities (dln N_d/dln α, −dln r_e/dln α, dln τ/dln N_d, dln LWP/dln N_d) used to quantify these relationships from observations."));

// 2. Foundations
children.push(H("2. Foundations (1950s–1970s): activation theory and the albedo hypothesis", HeadingLevel.HEADING_1));
children.push(P("The modern subject rests on two of Twomey's contributions, separated by fifteen years. The first is theoretical and concerns how many droplets form. In a 1959 paper, Twomey calculated the time variation of supersaturation during cloud formation and showed that a simple expression can be used to obtain the maximum supersaturation, and hence the number of nuclei activated, as a function of updraft velocity and the nucleus spectrum, with the predicted droplet concentrations agreeing with those actually observed (Twomey, 1959). The lower-bound approximation he introduced for the supersaturation integral is still the basis of many activation parameterizations (Shipway, 2015). Twomey and Warner (1967) later compared droplet concentrations measured in clouds with cloud-nucleus concentrations measured below cloud base and found them consistent, supporting the view that the nucleus population, together with the updraft, controls droplet concentration (Twomey and Warner, 1967). The key physical point for everything that follows is that N_d depends on both the aerosol and the updraft, and depends on the aerosol only sub-linearly, because each added nucleus consumes water vapor and depresses the peak supersaturation."));
children.push(P("The second contribution is the albedo hypothesis. Twomey's 1974 paper, 'Pollution and the planetary albedo', was the first publication to explain how enhanced cloud nuclei from anthropogenic pollution may increase the amount of solar radiation reflected by clouds, thereby increasing the planetary albedo; it received little attention when first proposed and was later awarded the Haagen-Smit Prize (Twomey, 1974; Atmospheric Environment editors, 2004). The 1977 follow-up made the competing radiative effects explicit: by increasing droplet concentration and thereby optical thickness, pollution increases cloud reflectance, but by increasing the absorption coefficient it decreases reflectance; calculations suggested the brightening dominates for thin to moderately thick clouds, whereas for sufficiently thick clouds the absorbing effect can become dominant (Twomey, 1977). The physical core is simple: for a fixed liquid water content and cloud depth, optical thickness scales as N_d^{1/3}, so adding droplets at constant water brightens the cloud."));
children.push(P("Two features of this foundation deserve emphasis because they shaped the next fifty years. First, the hypothesis was stated for a static cloud at fixed liquid water. Everything that was later called an 'adjustment' is a relaxation of that assumption. Second, the hypothesis was framed in terms of planetary albedo, i.e., the top-of-atmosphere (TOA) radiation budget. The surface radiation budget was not the focus, and that remains true of most of the literature today."));

// 3. 1980s-1990s
children.push(H("3. Expanding and testing the hypothesis (1980s–1990s)", HeadingLevel.HEADING_1));
children.push(H("3.1 Ship tracks: the first observational confirmation", HeadingLevel.HEADING_2));
children.push(P("The first clean observational test came from the 'anomalous cloud lines' noticed in early weather-satellite images and later attributed to ships. Coakley, Bernstein and Durkee (1987) showed that under stable meteorological conditions the effect of ship-stack exhaust on overlying clouds was detectable in daytime satellite images as an enhancement in cloud reflectivity at 3.7 μm, consistent with the exhaust supplying CCN that increase droplet number while reducing droplet size; the increase in droplet number raised 0.63 μm reflectivity despite the likelihood that the exhaust also contains absorbing particles (Coakley et al., 1987). Radke, Coakley and King (1989) then obtained simultaneous satellite and aircraft observations of two ship tracks off southern California during FIRE: droplet sizes decreased and droplet and total particle concentrations increased in the tracks, in situ upwelling radiance was enhanced at visible wavelengths and reduced at 2.2 μm, and the satellite showed enhanced reflectivity at 0.63 and 3.7 μm (Radke et al., 1989). These two papers established the ship track as the canonical natural experiment for aerosol–cloud interactions, a role it still plays."));
children.push(P("A detail from the FIRE case is worth noting because it foreshadows a long debate: the aircraft found that liquid water content increased in the tracks along with droplet number, which was not predicted by the fixed-water Twomey picture and was interpreted as drizzle suppression allowing water to accumulate (King et al., 1993, as summarized by NASA Earth Observatory; Radke et al., 1989). Whether LWP rises or falls in polluted clouds would become the central question of the 2010s."));

children.push(H("3.2 The Albrecht hypothesis and cloud-processed aerosol", HeadingLevel.HEADING_2));
children.push(P("Albrecht (1989) added a second mechanism. Using a numerical model of a cloudy boundary layer, he argued that increases in aerosol concentration over the oceans may increase the amount of low-level cloudiness through a reduction in drizzle, a process that regulates the liquid-water content and energetics of shallow marine clouds; the resulting increase in albedo would be in addition to the Twomey brightening (Albrecht, 1989). This 'second indirect', 'lifetime' or 'Albrecht' effect was for two decades treated as a positive feedback on the Twomey effect. It has since come under increasing scrutiny, and the quantitative relationship between aerosol, cloud fraction, LWP and lifetime is still debated (Feingold and Siebert, 2009)."));
children.push(P("In parallel, aerosol physicists were documenting what clouds do to the aerosol. Hoppel, Frick and Larson (1986) measured submicron size distributions over the tropical Atlantic and Pacific and found that remote marine distributions have two peaks with a minimum between them; they argued that non-precipitating clouds transfer material from the gas phase and from smaller particles into the larger mode and are responsible for the doubly-peaked distributions frequently observed over the oceans (Hoppel et al., 1986). Later airship measurements off Oregon confirmed that processing through non-precipitating stratus produces a distinct 'cloud residue' mode (Hoppel et al., 1994), and Hoppel, Frick and Fitzgerald (1996) showed that the separation of the size distribution into interstitial and residue modes makes it possible to infer the effective cloud supersaturation and droplet concentration from surface aerosol measurements when the boundary layer is well mixed, finding tropical effective supersaturations typically of 0.15–0.25% (Hoppel et al., 1996). The 'Hoppel minimum' thus became both a signature of cloud processing and a retrieval tool, and it is central to the EPCAPE work discussed in Section 6."));

children.push(H("3.3 Climate forcing and the susceptibility framework", HeadingLevel.HEADING_2));
children.push(P("The climate significance of the indirect effect was argued most forcefully by Charlson et al. (1992), who estimated that the climate forcing from anthropogenic sulfate was −1 to −2 W m⁻² globally averaged, comparable in magnitude to the greenhouse-gas forcing of the day but opposite in sign, and who noted that the perturbation of cloud albedo by anthropogenic aerosol also contributes substantially (Charlson et al., 1992). This put the indirect effect on the agenda of every subsequent IPCC assessment."));
children.push(P("Twomey (1991) introduced the term 'cloud susceptibility' to quantify the sensitivity of cloud reflectance to droplet number for a given reflectivity, with the corollary that a cloud forming in a pristine environment is more prone to albedo change when nuclei are added (Twomey, 1991; Atmospheric Environment editors, 2004). Platnick and Twomey (1994) made this operational from space: they defined susceptibility as the increase in albedo from adding one droplet per cubic centimeter at constant liquid water content, retrieved it from AVHRR droplet radius and optical thickness, and noted that marine stratus, being cleaner than continental clouds, is likely to have higher susceptibility (Platnick and Twomey, 1994). The underlying relation, Δr_e/r_e ≈ −(1/3)ΔN/N at fixed water, and the dominance of the optical-thickness term over the asymmetry-parameter and single-scattering-albedo terms, are laid out in Oreopoulos and Platnick (2006)."));
children.push(P("Pincus and Baker (1994) were the first to relax the fixed-thickness assumption analytically. Using a simple mixed-layer model of the cloud-topped marine boundary layer, they found that including the dependence of cloud thickness on particle number increased the albedo susceptibility by 50–200%, and concluded that the cloud-thickness response must be included for accurate prediction of global albedo (Pincus and Baker, 1994). This is the positive-adjustment view that the 2000s would complicate."));

children.push(H("3.4 First global surveys", HeadingLevel.HEADING_2));
children.push(P("Han, Rossow and Lacis (1994) produced the first near-global survey of effective droplet radii using ISCCP data, finding that droplet radii in continental water clouds are about 2–3 μm smaller than in marine clouds and about 1 μm smaller in Northern Hemisphere marine clouds than in the Southern Hemisphere, with height dependencies consistent with differences in aerosol vertical profiles (Han et al., 1994). A follow-up found that cloud albedo increases with decreasing droplet size over most continental areas and for all optically thicker clouds, but decreases with decreasing droplet size for optically thinner clouds over most oceans, and that for almost all clouds LWP increases with increasing droplet size (Han et al., 1998). The second finding is an early observational hint that LWP and N_d co-vary in ways that can mask or even reverse the Twomey signal, a theme that returns in Section 5."));

children.push(H("3.5 The state of the field in 1993: the Hobbs volume", HeadingLevel.HEADING_2));
children.push(P("A useful snapshot of the field at the end of this era is the edited volume *Aerosol–Cloud–Climate Interactions* (Hobbs, 1993), which grew out of presentations at the 1991 IUGG assembly in Vienna. Its preface frames the subject as six interactions among aerosol, clouds and climate, \"many of which we are only just beginning to understand, let alone incorporate into climate models\" (Hobbs, 1993, Preface). Five of its chapters bear directly on this review, and each closes with a list of outstanding problems. Hobbs's own chapter concludes that ship tracks \"well demonstrate\" the potential effect of aerosol on cloud structure and radiative properties, but that \"the regional and global effects of aerosol on cloud radiative properties remain uncertain\"; that a global inventory of the principal sources and nature of CCN is required; that the role of organics in CCN formation \"is potentially important but has not been quantified\"; that long time-series of CCN spectra are needed at a variety of locations; and that the role of clouds as a source of aerosol and CCN is potentially of global importance but \"not yet settled\" (Hobbs, 1993, Ch. 2). The same chapter records the then-current status of the DMS–cloud–climate (CLAW) hypothesis, noting that whether DMS emissions increase with temperature \"is not known\", and remarks that \"too many theories are chasing too few measurements\" (Hobbs, 1993, Ch. 2)."));
children.push(P("Harshvardhan's chapter on aerosol–climate interactions judged the direct forcing to be known \"to within a factor of 2 or 3\" but stated that \"the same cannot be said of the indirect forcing through changes in cloud microphysics\". It identified the primary hurdle as the modeling of cloud feedbacks, noting that the range of cloud shortwave forcing among the general circulation models of the day exceeded the total aerosol forcing by an order of magnitude, and concluded that the success of any attempt to model or monitor aerosol effects \"will ultimately rest on our ability to isolate the aerosol signal from the much more dominant effect of changes in cloudiness\" (Harshvardhan, 1993). King's chapter on the radiative properties of clouds flagged the \"anomalous absorption paradox\" (aircraft measurements consistently suggesting more solar absorption by clouds than theory predicts for liquid water and water vapor) as a four-decade-old discrepancy, while noting that the bulk of the then-recent evidence pointed to water-vapor absorption in the near-infrared window regions rather than to the droplets; it closed with the observations that there had been \"a longstanding tendency for too many theories to chase too few observations\", that spectral and angular measurements with collocated microphysics were the way forward, and that retrieval schemes based on Mie theory and plane-parallel radiative transfer had not yet been extended to horizontally inhomogeneous clouds (King, 1993). Heymsfield's chapter listed, among the measurements needed before the effects of stratiform clouds on climate could be evaluated realistically, quantitative criteria for defining cloud types, CCN concentrations as a function of geographic location and altitude, and droplet size distributions and liquid water contents in stratus and stratocumulus \"for a wide range of geographical areas\" (Heymsfield, 1993). Jaenicke's chapter on tropospheric aerosol emphasized the extreme spatial and temporal variability of the aerosol, the lack of standardized and intercompared instrumentation, the question of whether \"sulfate aerosols, in the strict sense of the term, exist, or are all aerosols mixed in nature\", and the need for long time series obtained \"mainly for basic understanding\" rather than for monitoring alone (Jaenicke, 1993). Sundqvist's chapter on cloud parameterization noted that only vertically integrated cloud water could then be measured and that knowledge of how to parameterize cloud cover was \"regrettably poor\" (Sundqvist, 1993). Section 10.2 returns to each of these problems and asks which have since been answered."));

// 4. 2000s
children.push(H("4. The remote-sensing era (2000s): measuring the effect and discovering the feedbacks", HeadingLevel.HEADING_1));
children.push(H("4.1 Satellite statistics", HeadingLevel.HEADING_2));
children.push(P("With POLDER and MODIS, the indirect effect could be surveyed statistically. Bréon, Tanré and Generoso (2002) found cloud droplet size largest (14 μm) over remote tropical oceans and smallest (6 μm) over polluted continental areas, derived a mean statistical relationship between droplet radius and aerosol load, and found droplet size better correlated with an aerosol index representative of column aerosol number than with aerosol optical thickness (Bréon et al., 2002). The IPCC Fourth Assessment nonetheless cautioned that the disparity among satellite-derived sensitivities suggested a quantitative estimate of the albedo effect from remote sensors was problematic, and that satellite aerosol and cloud retrievals are not coincident because an aerosol index is not determined in the presence of clouds (IPCC, 2007). Lohmann and Feichter (2005) reviewed the state of knowledge, emphasizing that while the Twomey effect had received most attention and was traditionally the only indirect forcing considered in transient climate simulations, a multitude of other effects exist and need to be considered (Lohmann and Feichter, 2005)."));

children.push(H("4.2 Ground-based remote sensing at ARM sites", HeadingLevel.HEADING_2));
children.push(P("Ground-based remote sensing offered a way around the satellite problem of non-coincident aerosol and cloud retrievals. Feingold et al. (2003) reported the first measurements of the Twomey effect from ground-based sensors at the ARM Southern Great Plains (SGP) site. They explicitly addressed the LWP confound: in studies that do not consider LWP, droplets may be smaller because the cloud has less water rather than because there are more condensation sites. Their approach compared clouds of similar LWP, retrieving r_e from cloud radar and microwave radiometer and representing aerosol by sub-cloud Raman lidar extinction, and defined the indirect-effect metric IE = −dln r_e/dln α (Feingold et al., 2003). Kim et al. (2003) used narrowband-radiometer cloud optical depth and microwave-radiometer LWP at SGP to relate droplet size to aerosol, and Kim et al. (2008) examined the role of adiabaticity in the first indirect effect; an associated ARM study found that the consistently steady, thin stratus at Point Reyes were closer to adiabatic and showed better ACI efficacy than SGP clouds because they formed in a more homogeneous, less entrainment-driven environment (Kim et al., 2008; Kim et al., ARM poster)."));
children.push(P("The most complete ground-based assessment of the decade, and the closest analog to EPCAPE, is McComiskey et al. (2009), from the 2005 ARM Mobile Facility deployment at Point Reyes, California. The average ACI_N (dln N_d/dln α) was 0.48, within a physically plausible range of 0–1, but values varied between 0.18 and 0.69 depending on the constant-LWP assumption, the relative value of LWP, the N_d retrieval method, the aerosol size distribution, updraft velocity, and the scale and resolution of observations (McComiskey et al., 2009). The spread is the point: the metric is at least as sensitive to methodology as to physics."));

children.push(H("4.3 The entrainment–sedimentation feedback and cloud thinning", HeadingLevel.HEADING_2));
children.push(P("The decisive conceptual development of the 2000s came from large-eddy simulation (LES). Ackerman et al. (2004) showed that the LWP response of stratocumulus to aerosol depends on the humidity of the air above the cloud, with drying by entrainment able to overwhelm drizzle suppression (Ackerman et al., 2004; this paper is in the project folder). Bretherton, Blossey and Uchida (2007) isolated the mechanism: in agreement with Ackerman et al., droplet sedimentation decreases entrainment and thereby increases LWP, but their simulations suggested this occurs not through reduced boundary-layer turbulence but because sedimentation removes liquid water from the entrainment zone, inhibiting both entrainment-induced evaporative cooling and longwave radiative cooling; since sedimentation rate is inversely related to droplet (and presumably aerosol) concentration and nearly non-drizzling stratocumulus are widespread, this effect should be climatically significant (Bretherton et al., 2007). The implication runs opposite to Albrecht: more aerosol means smaller, slower-falling droplets, more evaporation at cloud top, more efficient entrainment, and a thinner cloud."));
children.push(P("Wood (2007) placed both responses in a mixed-layer framework. Applying perturbation theory, he found that for cloud-base heights below about 400 m, increasing N_d leads to cloud thickening in accordance with the Albrecht hypothesis, but for higher cloud bases thinning occurs, which increasingly cancels the Twomey effect; on longer time scales an invariable thickening response is found, so the net effect depends on the timescale over which aerosol perturbations are modified (Wood, 2007). The sign of the LWP adjustment thus depends on the unperturbed state and on time, not only on microphysics."));

children.push(H("4.4 Activation regimes and the buffered-system view", HeadingLevel.HEADING_2));
children.push(P("Two 2009 papers closed the decade by reframing the problem. Reutter et al. (2009), using a cloud parcel model with κ-Köhler activation, identified three regimes of droplet formation depending on the ratio of updraft to aerosol number: an aerosol-limited regime (high w/N_CN, S_max above about 0.5%, activated fraction above about 90%) in which N_d is directly proportional to N_CN and practically independent of w; an updraft-limited regime (low w/N_CN, S_max below about 0.2%, activated fraction below about 20%); and a transitional regime between them (Reutter et al., 2009). Although developed for pyro-convective conditions, the regime diagram is the standard way to ask whether a given cloud can 'see' an aerosol perturbation at all."));
children.push(P("Stevens and Feingold (2009) argued that the difficulty of untangling relationships among aerosol, clouds and precipitation reflects the inadequacy of existing tools and a failure to account for processes that buffer cloud and precipitation responses to aerosol perturbations, and that research should focus on understanding specific regimes rather than lumping all cloud types together (Stevens and Feingold, 2009). The 'buffered system' framing has been the dominant interpretive lens since."));

// 5. 2010s
children.push(H("5. Quantification, confounding, and the LWP debate (2010s)", HeadingLevel.HEADING_1));
children.push(H("5.1 Ship tracks revisited with active sensors", HeadingLevel.HEADING_2));
children.push(P("Christensen and Stephens (2011) used CALIOP and CloudSat to separate ship-track responses by mesoscale regime. In both closed and open cells the microphysical changes were consistent with the Twomey hypothesis, but the macrophysics differed: in open cells polluted clouds had 16% higher tops and 39% more liquid water, whereas in closed cells cloud-top height did not change and liquid water fell by 6%; in closed cells the microphysical contribution to the optical-depth change was three times the macrophysical contribution, while in open cells the opposite held (Christensen and Stephens, 2011). This was direct observational support for the LES prediction that non-precipitating, closed-cell stratocumulus thin when polluted."));

children.push(H("5.2 Retrieval uncertainty and the scale problem", HeadingLevel.HEADING_2));
children.push(P("As ground-based products matured, their disagreements became visible. Zhao et al. (2012) compared nine ARM cloud retrievals and found large systematic discrepancies, particularly for liquid and ice effective radius, rooted in the retrieval theoretical bases, assumptions, and input and constraint parameters; differences among some products exceeded the uncertainties the developers themselves reported (Zhao et al., 2012). Huang et al. (2012) found that the mean MICROBASE r_e at SGP was more than 6 μm lower than the University of Utah product, with the discrepancy reduced to within 1 μm when raining and mixed-phase columns were excluded, and attributed the large r_e differences mainly to rain contamination and the assumptions about droplet concentration used in the algorithms (Huang et al., 2012). Lim et al. (2016) validated the ARM NDROP droplet-number product, which combines MFRSR optical depth and MWR LWP for single-layer warm clouds, against RACORO aircraft data and found that it reproduces the primary mode of the in situ distribution but produces too wide a distribution with too-frequent high N_d, partly because of MWR error at low LWP (Lim et al., 2016). These papers matter for any ARM-based study because they show that an apparent aerosol–microphysics relationship can be an artifact of the retrieval's own assumptions."));
children.push(P("McComiskey and Feingold (2012) framed the 'scale problem': analyzing LES output for three cloud fields, they showed that the ACI metric dln τ/dln N_d increased as a result of averaging, more so for heterogeneous fields (McComiskey and Feingold, 2012, as summarized by Feingold et al., 2022). Sena, McComiskey and Feingold (2016) then took the long view with 14 years of SGP data. Instead of microphysical metrics, they analyzed macroscopic variables and found that on a daily basis aerosol showed no correlation with cloud radiative properties (correlation −0.01 ± 0.03) whereas LWP showed a clear signal (0.56 ± 0.02); microphysical ACI estimates were very uncertain and depended strongly on methodology, retrieval technique and averaging scale (Sena et al., 2016). For a continental site, the influence of aerosol on shallow-cloud albedo and radiative effect was weak, with macroscopic cloud properties and dynamics playing a much larger role."));
children.push(P("Grosvenor et al. (2018) reviewed satellite N_d retrieval, inferring a total relative uncertainty of 78% for pixel-level retrievals in homogeneous, optically thick stratiform clouds with favorable geometry, reduced to 54% for 1°×1° averages, with the uncertainty dominated by errors in r_e (Grosvenor et al., 2018). Mülmenstädt and Feingold (2018) reviewed why quantifying ERFaci in liquid clouds remained so difficult, calling for much greater attention to the scale problem and for a shift from untangling aerosol and meteorology toward understanding their co-variability (Mülmenstädt and Feingold, 2018)."));

children.push(H("5.3 Aerosol proxies and the pre-industrial problem", HeadingLevel.HEADING_2));
children.push(P("Two papers undermined assumptions on the aerosol side. Carslaw et al. (2013) performed a sensitivity analysis on a global model and found that 45% of the variance of aerosol forcing since about 1750 arises from uncertainties in natural emissions, while only 34% is associated with anthropogenic emissions; nearly half of the uncertainty in the radiative effect of aerosols on clouds derives from poor knowledge of pre-industrial natural aerosol (Carslaw et al., 2013). Stier (2016) used a self-consistent global model to show that over 71% of the globe the correlation between CCN at 0.2% supersaturation at cloud base and aerosol optical depth is below 0.5, so that AOD variability explains only 25% of CCN variance; the limitation applies to ground-based passive sensing such as AERONET as well as to satellites (Stier, 2016). Both results argue for in situ CCN and size-distribution measurements of the kind EPCAPE provides."));

children.push(H("5.4 Ground-based ACI in marine regimes", HeadingLevel.HEADING_2));
children.push(P("Dong et al. (2014) generated a 19-month record of cloud fraction and single-layer marine boundary-layer cloud properties from the ARM deployment on Graciosa Island, Azores, and found that different air-mass sources had significant impacts on cloud microphysics and surface CCN (Dong et al., 2014). Hudson, Noble and Tabor (2015) showed that Hoppel minima in high-resolution CCN spectra serve as a diagnostic of effective cloud supersaturation, including for polluted California stratus sampled during MASE (Hudson et al., 2015); related work found higher droplet concentrations in stratus grown on bimodal, cloud-processed CCN than on unimodal CCN, and emphasized that in stratus the vertical-velocity variance σ_w is the other major determinant of N_d (Hudson and Noble, 2014; Hudson and Noble, 2018). Zheng et al. (2022, discussed below) extended this line to the Eastern North Atlantic."));

children.push(H("5.5 Natural experiments and the LWP adjustment", HeadingLevel.HEADING_2));
children.push(P("The LWP adjustment became the central quantitative question of the late 2010s. Malavelle et al. (2017) used the 2014–2015 Holuhraun fissure eruption as a natural experiment: the sulfur dioxide reduced liquid-cloud droplet size consistent with expectations, producing a global-mean forcing of about −0.2 W m⁻² for September–October 2014, but had no discernible effect on cloud amount or LWP, allowing climate models with an excessive LWP response to be rejected (Malavelle et al., 2017). Gryspeerdt et al. (2019) used joint-probability histograms of N_d and LWP from satellite data and found the N_d–LWP relationship negative in the majority of regions, suggesting aerosol-induced LWP reductions could offset a significant fraction of RFaci; however, the response to volcanic and shipping perturbations indicated that the correlation overestimates the causal effect because of confounders, so the result serves as an upper bound on the LWP forcing (Gryspeerdt et al., 2019). Toll et al. (2019) measured polluted clouds downwind of refineries, smelters, power plants, cities, wildfires and ships and found that aerosol-induced LWP increases from suppressed rain and decreases from enhanced evaporation partially cancel, yielding a relatively weak average decrease that offsets about 23% of the cooling from increased droplet number (Toll et al., 2019). A dissenting satellite-based view held that aerosol-driven droplet concentrations dominate the coverage and water of oceanic low clouds (Rosenfeld et al., 2019); that claim has been contested by the confounding analyses cited above and in Section 6."));

// 6. 2020s
children.push(H("6. The current decade (2020–2026): bounding the forcing and testing causality", HeadingLevel.HEADING_1));
children.push(H("6.1 Assessments", HeadingLevel.HEADING_2));
children.push(P("Bellouin et al. (2020) combined modeling, theory and observations to bound the industrial-era forcing: a 68% confidence interval for total aerosol ERF of −1.6 to −0.6 W m⁻² (90%: −2.0 to −0.4 W m⁻²), of similar width to the previous IPCC assessment but shifted toward more negative values. They judged that a robust theoretical foundation and convincing evidence constrain the forcing from aerosol-driven increases in droplet number, but that the influence on liquid cloud water and cloud fraction is less clear (Bellouin et al., 2020). This assessment fed into the IPCC Sixth Assessment Report's energy-budget chapter (Forster et al., 2021). Quaas et al. (2020) reviewed the satellite constraint on the Twomey effect and identified four key uncertainties: quantifying cloud-active aerosol at or above cloud base, quantifying N_d, the statistical approach for inferring sensitivity, and the anthropogenic perturbation itself; they concluded that past approaches have likely underestimated the true sensitivity, and that AOD-type retrievals suffer from lack of vertical resolution, size and hygroscopicity information (Quaas et al., 2020)."));

children.push(H("6.2 Ship tracks at scale and the IMO 2020 experiment", HeadingLevel.HEADING_2));
children.push(P("Diamond et al. (2020) used universal kriging to estimate counterfactual cloud fields in the southeast Atlantic shipping corridor and attributed a significant increase in cloud reflectivity to enhanced droplet number; in the morning the brightening was consistent with microphysics alone, whereas in the afternoon microphysical brightening was offset by decreases in total cloud water, and several years of data were needed to identify the signal (Diamond et al., 2020). Glassmeier et al. (2021) then showed by comparing LES ensembles with satellite analyses that ship-track studies cannot be generalized to climatological forcing: because tracks are too short-lived for the cloud to reach its thinner steady state, ship-track-derived sensitivities of non-precipitating stratocumulus overestimate the cooling by up to 200% (Glassmeier et al., 2021). Feingold, Goren and Yamaguchi (2022) quantified the aggregation biases in albedo susceptibility using 127 LES cases, showing spatial aggregation biases of hundreds of percent that are partly countered by temporal aggregation, with key uncertainties in the adiabatic N_d retrieval and the aerosol–cloud correlation (Feingold et al., 2022). Christensen et al. (2022) synthesized the opportunistic-experiment literature and concluded that cloud albedo perturbations are strongly sensitive to background meteorology and that strong LWP increases are largely ruled out by averaging across experiments, while it remains unclear how reliably the relationships scale globally (Christensen et al., 2022)."));
children.push(P("Machine learning changed the sample size. Yuan et al. (2022) produced the first global ship-track climatology, with track frequency more than ten times a previous survey, and showed that the 2020 fuel regulation together with the pandemic reduced ship-track frequency to its lowest level in decades, reducing the aerosol indirect forcing from shipping by about 46% (Yuan et al., 2022). Watson-Parris et al. (2022) catalogued more than a million tracks and found a marked but non-linear decline: an 80% reduction in SO_x emissions produced only a 25% reduction in detected tracks (Watson-Parris et al., 2022). Manshausen et al. (2022) tracked ship plumes regardless of visibility and found that invisible tracks show a droplet-number increase roughly half that of visible tracks but a positive LWP response in non-precipitating clouds rather than the negative one seen in visible tracks, implying that visible-track studies suffer from selection bias and that the LWP response may translate to a larger cooling (Manshausen et al., 2022). Diamond (2023) detected large-scale microphysical changes in the southeast Atlantic corridor after IMO 2020, estimating an instantaneous forcing of order 1 W m⁻² within the corridor and lending credence to global estimates of order 0.1 W m⁻² (Diamond, 2023). The sign of the LWP adjustment for shipping-polluted clouds is therefore still unsettled: visible-track and LES-steady-state analyses say negative; plume-tracking says positive in the trade-cumulus regime."));

children.push(H("6.3 Co-variability, morphology, and heuristic models", HeadingLevel.HEADING_2));
children.push(P("Possner et al. (2020) deconvolved boundary-layer depth and aerosol constraints on cloud water in subtropical stratocumulus, and Arola et al. (2022) showed that aerosol effects on clouds can be concealed by natural cloud heterogeneity and satellite retrieval errors, including spurious negative N_d–LWP relationships from r_e retrieval error in non-raining clouds (Possner et al., 2020; Arola et al., 2022, as summarized by Zhang et al., 2025). Goren et al. (2025) argued that the 'inverted-V' joint histogram of LWP against N_d, with its positive branch at low N_d and negative branch at high N_d, is driven by co-variability rather than causality (Goren et al., 2025). Hoffmann, Glassmeier and Feingold (2024) derived a two-equation heuristic model for cloud water adjustments in stratocumulus that agrees with LES and satellite data; it reveals a tight relationship between adjustments at low and high N_d, shows that adjustments in non-precipitating clouds tend to be positively biased by external perturbations, and that adjustments in precipitating clouds are barely susceptible (Hoffmann et al., 2024)."));
children.push(P("Goren, Choudhury and Feingold (2026) introduced a ternary-diagram continuum of stratocumulus morphology based on optical-thickness classes and computed susceptibilities conditioned on morphology from one year of MODIS/CERES data. They found S_LWP negative across all morphologies including precipitating ones, the strongest negative values (near −1) where intermediate-τ clouds dominate, and a net in-cloud albedo susceptibility S_net ranging from −0.3 to 0.3 by morphology but only 0.015 ± 0.007 when weighted by occurrence, because in the most common morphologies the LWP and Twomey susceptibilities largely offset (Goren et al., 2026). The paper notes that, using the Platnick–Twomey approximations, S_net = S_Ac + γ·S_LWP with S_Ac = (1−A_c)/3 and γ = (5/6)(1−A_c), the same decomposition that Feingold et al. (2022) write as S_o = (1−A_c)/3·[1 + (5/2) dln L/dln N_d]."));

children.push(H("6.4 Ground-based studies and the role of boundary-layer coupling", HeadingLevel.HEADING_2));
children.push(P("Ground-based work in this decade has concentrated on the Eastern North Atlantic and on the role of the boundary-layer state. Zheng et al. (2022) selected 20 non-precipitating single-layer cases at the ARM ENA site and found ACI_r (the relative change in r_e with respect to CCN at 0.2% supersaturation) ranging from −0.01 to 0.22, increasing with sub-cloud precipitable water vapor, and strengthened by boundary-layer turbulence that maintains a well-mixed layer connecting cloud microphysics to below-cloud CCN (Zheng et al., 2022). Aircraft profiles during ACE-ENA showed that coalescence scavenging and drizzle evaporation reduce CCN in the upper, cloud-containing part of a decoupled boundary layer, so surface measurements overestimate the CCN relevant to cloud formation under decoupled conditions (Wang et al., 2021). A 2026 preprint quantifies this: decoupling occurred about 32% of the time in both seasons, during which about 60% of accumulation-mode and 75% of Aitken-mode particles failed to reach the cloud layer, and sensitivity experiments showed accumulation-mode number to be the dominant control on N_d in summer with Aitken-mode number and size also mattering in winter, while updraft and hygroscopicity variations had weaker effects (Wang et al., 2026, preprint). These findings justify restricting ACI analyses to coupled cases, as the EPCAPE group has chosen to do."));

children.push(H("6.5 EPCAPE: the first results", HeadingLevel.HEADING_2));
children.push(P("The Eastern Pacific Cloud Aerosol Precipitation Experiment deployed ARM's first mobile facility at Scripps Pier and Mt. Soledad from February 2023 to February 2024 (Russell et al., 2025). Three studies have appeared so far."));
children.push(P("Dedrick et al. (2025), working with LASIC data from Ascension Island but establishing the method applied at EPCAPE, decomposed the Twomey effect into activation, competition and dynamical responses using two independent supersaturation retrievals. The competition response, in which added particles take up water faster and depress supersaturation, dampened the activation response by 12–35% and explained the diminished Twomey effect at high aerosol concentrations; the dynamical response was negligible, and the Twomey radiative forcing was correspondingly reduced by 12–35% (Dedrick et al., 2025; in project folder). Dedrick et al. (2026) then classified one year of EPCAPE size distributions into broad-accumulation, bimodal and broad-Aitken categories, with bimodal distributions exhibiting Hoppel minima indicative of recent and repeated cloud cycling. Scene- and parcel-based supersaturation retrievals were 0.03–0.13% whereas Hoppel-minimum-based estimates were 0.2–0.3%, reflecting maxima over ensembles of recent cloud cycles; retrieved supersaturations correlated positively with liquid water content and droplet number; and the authors concluded that during EPCAPE the signatures of local sources and scavenging overwhelm the competition-for-vapor signature seen in remote environments, with the implication that in polluted coastal environments efficient scavenging limits the cloud impact of added particles (Dedrick et al., 2026; in project folder)."));
children.push(P("Zhang et al. (2025) applied an explainable machine-learning framework (XGBoost with SHAP attribution) to about seven months of hourly EPCAPE data, using CCN-counter concentrations as a proxy for N_d and the two-channel MWR for LWP; radiosondes classified 76% of cases as coupled. Aerosols emerged as the dominant factor explaining LWP variability, surpassing each meteorological factor, and after removing meteorological co-variability the N_d–LWP relationship was negative and log-linear with a slope of −1.1 over 250–800 cm⁻³, attributed to entrainment drying; no positive branch appeared because precipitating cases were rare, the sensitivity was weaker in daytime, and the authors argued from back-trajectory and boundary-layer-height stratification that air-mass history was not the primary driver, while acknowledging that LES would be needed for a process-level test (Zhang et al., 2025). Chellappan et al. (2026, preprint) used self-organizing maps on ERA5 to classify April–October 2023 into nine synoptic regimes and found that regimes with anticyclone cores close to the pier produce reduced low-cloud fraction, shallower clouds and low LWP, that stagnant weak-anticyclone regimes carry the highest concentrations of small particles, and that partial inconsistency between N_d and aerosol concentration indicates that boundary-layer turbulence critically influences activation (Chellappan et al., 2026). Together these three papers cover the microphysical side of the EPCAPE aerosol–cloud question; none addresses surface radiation."));

// 7. Physics (new in revision 4)
require("./section7.js")({ H, rich, cell, tw: 9360, FONT, BODY }).forEach((x) => children.push(x));

// 8. Surface radiation theme
children.push(H("8. A cross-cutting theme: the surface radiation perspective", HeadingLevel.HEADING_1));
children.push(P("From Twomey (1974) onward the literature has been framed around planetary albedo, i.e., the TOA budget. The surface budget is physically coupled to it but has been studied far less in the ACI context, which makes it an attractive niche. This section collects the relevant strands in rough chronological order."));
children.push(P("Ground-based retrieval of stratus microphysics and radiative properties from combined radar, microwave radiometer and radiometer measurements was established by Dong et al. (1997, 1998), who developed and then parameterized relationships between microphysical and shortwave radiative properties of boundary-layer stratus at SGP (Dong et al., 1997; Dong et al., 1998; both in project folder). These retrievals are the ancestors of the MICROBASE and NDROP products whose caveats are discussed in Section 5.2. ARM's Broadband Heating Rate Profile (BBHRP) project then used radiative closure, i.e., comparing calculated surface and TOA fluxes with measurements, as the standard for evaluating cloud microphysical retrievals, with MICROBASE as the reference retrieval; at the North Slope of Alaska, an alternative retrieval gave noticeably better surface closure than MICROBASE, and surface closure was generally better than TOA closure (Mlawer et al., ARM proceedings; Shupe et al., ARM 2008 poster; BBHRP evaluation records). Microwave-radiometer LWP uncertainty was found to be largest below about 30 g m⁻² (CLOWD/BBHRP intercomparison, 2009)."));
children.push(P("Spectral surface measurements add information that broadband measurements lack. Marshak et al. (2009) found a spectrally invariant behavior in 1-s zenith radiance spectra from the ARM Shortwave Spectrometer as the sky transitions from cloudy to clear: the transition-zone spectrum is a linear mixture of the definitely-clear and definitely-cloudy spectra with a wavelength-independent weight (Marshak et al., 2009). Chiu et al. had earlier found a linear relationship between the sum and difference of 870 and 1640 nm radiances in the transition zone, with intercept set by aerosol and slope by cloud (Chiu et al., as cited by Marshak et al., 2009). These results rest on Koren et al. (2007), who found that 30–60% of the atmosphere labeled clear in satellite data is affected by a cloud–aerosol 'twilight zone' extending tens of kilometers from cloud edges (Koren et al., 2007, as summarized by Jahani et al., 2022). McBride et al. (2011) introduced a transmittance-based retrieval that uses the spectral slope between 1565 and 1634 nm to recover r_e sensitivity that the standard two-wavelength method lacks in transmission, with valid retrievals for 84% of thin-cloud cases versus 24% for the standard method (McBride et al., 2011). Eck et al. (2012) documented from AERONET that fog and stratocumulus dissipation leave large cloud-processed fine-mode particles and that AOD rises with fine-mode radius, so that pre- and post-cloud AOD differences carry a cloud-processing signal (Eck et al., 2012)."));
children.push(P("Two cautions apply to surface SW analysis of ACI. First, Sena et al. (2016), the only long-term study that directly asked whether aerosol affects the surface cloud radiative effect, found essentially no daily correlation at SGP while LWP explained most of the variance (Sena et al., 2016). Second, three-dimensional radiative effects are large under broken cloud: Gristey et al. (2020) found that only 3-D radiative transfer reproduces the bimodal distribution of surface solar irradiance under shallow cumulus, with local 1-D/3-D differences averaging more than 150 W m⁻² on one afternoon (Gristey et al., 2020). Any 1-D closure study must therefore be restricted to overcast, single-layer conditions."));
children.push(P("A simple theoretical expectation can be written down. For a conservatively scattering cloud, transmittance is approximately 1 − A_c, so the susceptibility of transmission to droplet number is approximately −A_c(1−A_c)/3·[1 + (5/2) S_LWP], using the Feingold et al. (2022) form (Sections 7.8 and 7.10 give the algebra). This predicts maximum sensitivity near A_c ≈ 0.5, a sign that reverses when S_LWP falls below −0.4, and a null result when S_LWP = −0.4. Against this expectation, Zhang et al.'s (2025) EPCAPE slope of −1.1 would predict surface transmission *increasing* with aerosol, while Goren et al.'s (2026) occurrence-weighted S_net of 0.015 predicts almost no signal at all. Either way, the surface test is a test of the adjustment, not just of Twomey brightening. This derivation is the author's extrapolation of the cited formulas and is not itself from the literature."));
children.push(P("EPCAPE's SCARPE sub-campaign, led by Dan Lubin, deployed spectral-filter and broadband radiometers at Mt. Soledad with the stated objectives of determining the response of cloud radiative properties to changing microphysics under changing aerosol regimes and of testing whether low-cost radiometers are sensitive to both LWP and r_e; the campaign page notes that without an independent LWP measurement, cloud optical depth is much less sensitive to r_e and large samples may be needed for statistical significance (ARM, EPCAPE-SCARPE campaign page; Lubin et al., 2026)."));

// 8. Synthesis
children.push(H("9. Where the field stands", HeadingLevel.HEADING_1));
children.push(P("Reading the literature in order, a few shifts stand out. The Twomey effect went from hypothesis (1974) to ship-track confirmation (1987–1989) to statistical measurement from space and ground (2002–2009) and is now regarded as the best-constrained part of ERFaci (Bellouin et al., 2020). The Albrecht effect went from a presumed positive feedback (1989–1994) to one competing process among several (2004–2009) to a response that, averaged over natural experiments, is weak or negative (2017–2022), with the sign in specific regimes still argued (2022–2026). The dominant methodological lesson of the 2010s was that ACI metrics are strongly sensitive to retrieval assumptions, averaging scale, and meteorological co-variability, so that a correlation is not a susceptibility and a susceptibility is not a forcing. The dominant lesson of the 2020s has been that the net albedo response is a small residual of two larger terms of opposite sign, so that regime- and morphology-conditioned analyses are required."));

const tw = 9360; // total table width (6.5 in)
const c1 = 3000, c2 = 3180, c3 = 3180;
const rows = [
  ["Question", "Status", "Key sources"],
  ["Does added aerosol increase N_d and decrease r_e at fixed LWP?", "Settled. Observed in ship tracks, volcanic plumes, satellite climatologies and ground-based retrievals.", "Coakley et al. 1987; Radke et al. 1989; Bréon et al. 2002; Feingold et al. 2003; Malavelle et al. 2017"],
  ["Is N_d linear in aerosol number?", "Settled that it is sub-linear; the competition response and updraft limitation reduce the sensitivity at high aerosol.", "Twomey 1959; Reutter et al. 2009; Dedrick et al. 2025, 2026"],
  ["Sign of the LWP adjustment in non-precipitating stratocumulus", "Mostly settled as negative (entrainment drying), but magnitude and regime dependence contested; invisible-track analyses find positive values in trade cumulus.", "Ackerman et al. 2004; Bretherton et al. 2007; Toll et al. 2019; Glassmeier et al. 2021; Manshausen et al. 2022; Goren et al. 2026"],
  ["Sign of the LWP adjustment in precipitating clouds", "Contested. The classic positive branch of the inverted-V may be a co-variability artifact.", "Albrecht 1989; Gryspeerdt et al. 2019; Goren et al. 2025, 2026; Hoffmann et al. 2024"],
  ["Net in-cloud albedo susceptibility", "Contested. One global estimate gives near zero when weighted by morphology; regional natural experiments give substantial brightening.", "Diamond et al. 2020; Goren et al. 2026"],
  ["Magnitude of global ERFaci", "Bounded but wide: −1.6 to −0.6 W m⁻² (68%) for total aerosol ERF.", "Bellouin et al. 2020; Forster et al. 2021"],
  ["Can AOD stand in for CCN?", "Settled that it is a poor proxy over most of the globe.", "Stier 2016; Quaas et al. 2020"],
  ["Are ground-based r_e and N_d retrievals adequate for ACI?", "Partly. Products disagree by several μm; NDROP is too broad at low LWP; assumptions can make correlations circular.", "Zhao et al. 2012; Huang et al. 2012; Lim et al. 2016; McComiskey et al. 2009"],
  ["Does aerosol measurably change surface SW under stratocumulus?", "Open. Only one long-term continental study (null result); no marine study found.", "Sena et al. 2016"],
];
